/// <reference types="node" />
/**
 * The simulation engine run on the real files in `public/data/`.
 *
 * The expected visibility numbers are the team's reference values, generated by the Python
 * pipeline (`python -m preprocess.reference` → docs/reference/visibility.json) from the same
 * files over the whole computed period. They are read from that file, so regenerating the
 * data and the reference together keeps this test in step. The TypeScript engine has to
 * reproduce them from the JSON alone.
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import type { SiteData, SitesDoc } from '../src/data/contract.ts'
import { J_PER_WH } from '../src/sim/energy.ts'
import { DEFAULT_SETTINGS, evaluateScenario, evaluateScenarios } from '../src/sim/evaluate.ts'
import { horizonAt, marginSeries, sunDiskFraction, windowsFromMargins } from '../src/sim/visibility.ts'

const DATA_DIR = fileURLToPath(new URL('../public/data/', import.meta.url))
const read = <T>(path: string): T => JSON.parse(readFileSync(DATA_DIR + path, 'utf8')) as T

const sites = read<SitesDoc>('sites.json')
const bySite: Record<string, SiteData> = Object.fromEntries(
  sites.sites.map((site) => [
    site.id,
    { site, ephemeris: read(`${site.id}/ephemeris.json`), horizon: read(`${site.id}/horizon.json`), terrain: read(`${site.id}/terrain.json`) } as SiteData,
  ]),
)

/** Shape of docs/reference/visibility.json (written by `python -m preprocess.reference`). */
interface RefWindow { startIndex: number; endIndex: number; durationS: number; openAtStart: boolean; openAtEnd: boolean }
interface RefSite {
  samples: number
  percentVisible: { sun: number; earth: number; both: number }
  sunDiskFractionMean: number
  neverVisible: { sun: boolean; earth: boolean }
  alwaysVisible: { sun: boolean; earth: boolean }
  events: { sun: number; earth: number }
  windows: { sun: RefWindow[]; earth: RefWindow[] }
  spotChecks: { index: number; body: 'sun' | 'earth'; azDeg: number; elDeg: number; horizonDeg: number; visible: boolean }[]
}
interface ReferenceDoc {
  coverage: { startUtc: string; stepS: number }
  horizonAtCases: { siteId: string; cases: { azDeg: number; expectedDeg: number }[] }
  sites: Record<string, RefSite>
}
const REFERENCE = JSON.parse(readFileSync(fileURLToPath(new URL('../docs/reference/visibility.json', import.meta.url)), 'utf8')) as ReferenceDoc

describe('the reference file and the data describe the same period and sites', () => {
  it('covers every site in sites.json with the same time base', () => {
    expect(Object.keys(REFERENCE.sites).sort()).toEqual(sites.sites.map((s) => s.id).sort())
    expect(REFERENCE.coverage.startUtc).toBe(sites.coverage.startUtc)
    expect(REFERENCE.coverage.stepS).toBe(sites.coverage.stepS)
    for (const [siteId, ref] of Object.entries(REFERENCE.sites)) expect(bySite[siteId].ephemeris.count).toBe(ref.samples)
  })
})

describe('horizonAt reproduces the pipeline test vectors (incl. the 359.9° → 0° wrap)', () => {
  const { siteId, cases } = REFERENCE.horizonAtCases
  for (const c of cases) {
    it(`${siteId} az ${c.azDeg}°`, () => {
      // reference values are rounded to 5 decimals
      expect(Math.abs(horizonAt(bySite[siteId].horizon, c.azDeg) - c.expectedDeg)).toBeLessThan(1e-4)
    })
  }
})

describe('visibility over the whole computed period matches the pipeline reference', () => {
  for (const [siteId, ref] of Object.entries(REFERENCE.sites)) {
    it(siteId, () => {
      const { ephemeris, horizon } = bySite[siteId]
      const pct = (n: number) => (100 * n) / ephemeris.count
      const margins = { sun: marginSeries(ephemeris.sun, horizon, 0, ephemeris.count), earth: marginSeries(ephemeris.earth, horizon, 0, ephemeris.count) }

      for (const body of ['sun', 'earth'] as const) {
        const margin = margins[body]
        const visible = margin.reduce((n, m) => n + (m > 0 ? 1 : 0), 0)
        expect(Math.abs(pct(visible) - ref.percentVisible[body])).toBeLessThan(0.006)
        expect(visible === 0).toBe(ref.neverVisible[body])
        expect(visible === ephemeris.count).toBe(ref.alwaysVisible[body])

        const windows = windowsFromMargins(margin, ephemeris.stepS)
        expect(windows.map((w) => [w.startIndex, w.endIndex, w.openAtStart, w.openAtEnd])).toEqual(
          ref.windows[body].map((w) => [w.startIndex, w.endIndex, w.openAtStart, w.openAtEnd]),
        )
        // rises and sets inside the period (window edges that are not the data boundary)
        const events = windows.reduce((n, w) => n + (w.openAtStart ? 0 : 1) + (w.openAtEnd ? 0 : 1), 0)
        expect(events).toBe(ref.events[body])
        // interpolated rise/set lies within the step before the first / after the last visible sample
        for (const w of windows) {
          if (!w.openAtStart) expect(w.startS / ephemeris.stepS).toBeGreaterThan(w.startIndex - 1)
          expect(w.startS / ephemeris.stepS).toBeLessThanOrEqual(w.startIndex)
          expect(w.endS / ephemeris.stepS).toBeGreaterThanOrEqual(w.endIndex - 1)
          if (!w.openAtEnd) expect(w.endS / ephemeris.stepS).toBeLessThan(w.endIndex)
        }
      }

      const both = margins.sun.reduce((n, m, i) => n + (m > 0 && margins.earth[i] > 0 ? 1 : 0), 0)
      expect(Math.abs(pct(both) - ref.percentVisible.both)).toBeLessThan(0.006)

      // contract's partial-disk approximation, averaged over every sample (rounded to 4 decimals)
      const diskSum = margins.sun.reduce((s, m, i) => s + sunDiskFraction(m, ephemeris.sun.distanceM[i]), 0)
      expect(Math.abs(diskSum / ephemeris.count - ref.sunDiskFractionMean)).toBeLessThan(6e-5)

      for (const s of ref.spotChecks) {
        const series = ephemeris[s.body]
        expect(Math.abs(series.azDeg[s.index] - s.azDeg)).toBeLessThan(1e-9)
        expect(Math.abs(series.elDeg[s.index] - s.elDeg)).toBeLessThan(1e-9)
        expect(Math.abs(horizonAt(horizon, s.azDeg) - s.horizonDeg)).toBeLessThan(1e-6)
        expect(margins[s.body][s.index] > 0).toBe(s.visible)
      }
    })
  }
})

describe('default mission (15 Nov 2026, 7 days, example hardware) on real data', () => {
  const start = '2026-11-15T00:00:00Z'
  const results = Object.fromEntries(sites.sites.map((s) => [s.id, evaluateScenario(bySite[s.id], start, DEFAULT_SETTINGS)]))

  it('covers 7 days at 10-minute steps from the right sample', () => {
    for (const r of Object.values(results)) {
      expect(r.startIndex).toBe(14 * 144)
      expect(r.count).toBe(7 * 144 + 1)
      expect(r.model.ephemerisSource).toBe(bySite[r.siteId].ephemeris.source)
    }
  })

  it('keeps the energy books balanced', () => {
    for (const r of Object.values(results)) {
      const s = r.summary
      const capacity = r.batteryCapacityJ
      expect(s.energyDemandJ / J_PER_WH).toBeGreaterThanOrEqual(200 * 168 - 1)
      expect(s.energyDemandJ / J_PER_WH).toBeLessThanOrEqual(300 * 168 + 1)
      // a tracking 2 m² panel near perihelion gives 544–566 W while the Sun is up
      const sunHours = s.sunVisibleFraction * 168
      expect(s.energyGeneratedJ / J_PER_WH).toBeGreaterThanOrEqual(544 * sunHours - 1)
      expect(s.energyGeneratedJ / J_PER_WH).toBeLessThanOrEqual(566 * sunHours + 1)
      expect(s.minSocFraction).toBeGreaterThanOrEqual(0)
      expect(s.finalSocFraction).toBeLessThanOrEqual(1)
      expect(Math.max(...r.socJ)).toBeLessThanOrEqual(capacity)
      if (s.keepsBatteryReserve) expect(s.minSocFraction).toBeGreaterThanOrEqual(DEFAULT_SETTINGS.reserveFraction)
      else expect(s.minSocFraction).toBeLessThan(DEFAULT_SETTINGS.reserveFraction)
    }
  })

  it('tells the Shackleton wall from the ridge 1.9 km away', () => {
    const wall = results.Site04.summary
    const ridge = results.Site04R.summary
    expect(ridge.sunVisibleFraction).toBe(1)
    expect(ridge.keepsBatteryReserve).toBe(true)
    expect(ridge.unmetEnergyJ).toBe(0)
    expect(wall.sunVisibleFraction).toBeLessThan(ridge.sunVisibleFraction)
    expect(wall.earthVisibleFraction).toBe(0)
    expect(wall.earthOutageWithinLimit).toBe(false)
  })

  it('compares up to three scenarios with shared settings', () => {
    const three = evaluateScenarios(
      [
        { siteId: 'Site04', startUtc: start },
        { siteId: 'Site04R', startUtc: start },
        { siteId: 'Site04R', startUtc: '2026-11-18T00:00:00Z' },
      ],
      DEFAULT_SETTINGS,
      bySite,
    )
    expect(three.map((r) => r.siteId)).toEqual(['Site04', 'Site04R', 'Site04R'])
    expect(three[2].startIndex - three[1].startIndex).toBe(3 * 144)
  })

  it('refuses a mission that runs past the end of the data', () => {
    expect(() => evaluateScenario(bySite.Site01, '2026-12-28T00:00:00Z', DEFAULT_SETTINGS)).toThrow(/computed period/)
    expect(() => evaluateScenario(bySite.Site01, '2026-12-25T00:00:00Z', DEFAULT_SETTINGS)).not.toThrow()
  })
})
